    _P8_FUSION_REPORT.clear()
    _P8_FUSION_REPORT.update(getattr(_T19_PARENT, 'telemetry', {}))
    _P8_FUSION_REPORT.update({'production.'+k:v for k,v in _T19_REPORT.items()})
